import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { Chess } from 'chess.js';
import { repetitionLevels, positionKey } from '../src/repetition.js';
import { toUci } from '../src/game.js';

// Generated by the training repository (benchmarks/repetition_fixture.py) from repetition.py.
const fixture = JSON.parse(await readFile(new URL('./fixtures/repetition-levels.json', import.meta.url)));

test('levels match the Python reference for every fixture position', () => {
  let moves = 0;
  for (const c of fixture.cases) {
    const board = new Chess(c.fen);
    for (const uci of c.history) board.move({ from: uci.slice(0, 2), to: uci.slice(2, 4), promotion: uci[4] });
    assert.equal(board.fen().split(' ').slice(0, 4).join(' '), c.position.split(' ').slice(0, 4).join(' '), c.name);
    const legal = board.moves({ verbose: true }).map(toUci);
    assert.deepEqual([...legal].sort(), Object.keys(c.levels).sort(), c.name);
    const levels = repetitionLevels(c.fen, c.history, legal);
    assert.deepEqual(Object.fromEntries(legal.map((m, i) => [m, levels[i]])), c.levels, c.name);
    moves += legal.length;
  }
  assert.ok(moves > 10000);
});

test('en passant is part of the position only when the capture is legal', () => {
  const capture = new Chess('4k3/8/8/8/3p4/8/4P3/4K3 w - - 0 1'); capture.move('e4');
  assert.match(positionKey(capture), / e3$/);
  const quiet = new Chess('4k3/8/8/8/8/8/4P3/4K3 w - - 0 1'); quiet.move('e4');
  assert.match(positionKey(quiet), / -$/);
});
